using System;using System.IO;using System.Linq;using System.Collections;using System.Reflection;using UnityEngine;using Bokumyaku.Presentation;
public static class DrainFlowCheck {
static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(g==null||!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var world=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",flags).GetValue(g);var time=typeof(InkBattleWorld).GetField("visualTime",flags);float old=(float)time.GetValue(world);string snapshot=JsonUtility.ToJson(g.Run.CaptureState());Action<bool> render=r=>world.Render(g.Run,g.BranchOverlay,1,true,r,true,BokumyakuBattleHud.GetBattleViewport());
render(false);var enemies=(IDictionary)typeof(InkBattleWorld).GetField("enemies",flags).GetValue(world);object leechView=null;SpriteRenderer[] parts=null;foreach(var v in enemies.Values){var d=(SpriteRenderer[])v.GetType().GetField("drain").GetValue(v);if(d!=null){parts=d;leechView=v;break;}}if(parts==null||parts.Length!=9||parts.Any(p=>!p.enabled))throw new Exception("Drain missing");
time.SetValue(world,1f);render(false);var first=parts[6].transform.localPosition;time.SetValue(world,1.2f);render(false);if(first==parts[6].transform.localPosition)throw new Exception("Flow stationary");render(true);first=parts[6].transform.localPosition;time.SetValue(world,2f);render(true);if(first!=parts[6].transform.localPosition)throw new Exception("Reduced flow moved");
leechView.GetType().GetField("dying").SetValue(leechView,true);render(false);if(parts.Any(p=>p.enabled))throw new Exception("Drain remained after death");leechView.GetType().GetField("dying").SetValue(leechView,false);world.Reset(g.Run);if(parts.Any(p=>p.gameObject.activeInHierarchy))throw new Exception("Pool leak");time.SetValue(world,old);render(g.ReducedMotion);if(snapshot!=JsonUtility.ToJson(g.Run.CaptureState()))throw new Exception("Simulation changed");
var result=new{passed=true,parts=9,flowMoves=true,reducedStatic=true,resetReleased=true,deathDisabled=true,snapshotUnchanged=true,width=Screen.width,height=Screen.height,method="Forced attached leech; presentation time advanced independently; no PlayerPrefs changes"};File.WriteAllText(Path.GetFullPath("../docs/evidence/drain-flow.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/drain-flow.png"));return result;
}}
